            t.exec("usePestleOnKarambwan", t.player.use_item_on_item, "pestle_and_mortar", "tbwt_poorly_cooked_karambwan")
            t.exec("usePestleOnKarambwan.has", t.inv.await, "tbwt_poisonous_karambwan_paste", 1, 20)
            t.exec("usePasteOnSpear", t.player.use_item_on_item, "tbwt_poisonous_karambwan_paste", "iron_spear")
            t.exec("usePasteOnSpear.has", t.inv.await, "tbwt_iron_spear_kp", 1, 20)

            -- Tamayu (2845,3041): first talk is the good-news chain, then "When will you succeed?" + Yes plays the hunt cutscene
            t.exec("goto-talkToTamayu1", t.player.goto_tile, 2846, 3041, 0)
            t.exec("talkToTamayu1-news", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("talkToTamayu1-news-dialog", t.chat.play, {
                "player:Tamayu, first son of Timfraku",
