                "player:Your father requests",
                "npc:Then know this",
                "npc:I vow upon the blood",
                "player:You could slay it",
                "npc:No!",
            })
            t.ticks(2)
            t.exec("talkToTamayu1", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("talkToTamayu1-dialog", t.chat.play, {
                "options",
                "choose:When will you succeed?",
                "player:When will you succeed",
                "npc:When the gods bless me",
                "options",
                "choose:Yes",
                "player:Lead the way",
            })
            t.exec("talkToTamayu1.cutscene", t.cutscene.await, "talkToTamayu1", { expect = { { op = "reset" } } })
            t.exec("talkToTamayu1-assess", t.chat.play, {
                "npc:I simply cannot match",
                "npc:I cannot do enough damage",
                "npc:",
            })
            t.ticks(2)

            t.exec("givePotion", t.player.use_on, "4dose1agility", t.player.by_symbol("npc", "tbwt_tamayu"))
