            t.ticks(6)
            t.exec("givePotion-agile", t.chat.play, { "npc:I feel agile enough" })
            t.ticks(2)
            t.exec("giveSpear", t.player.use_on, "tbwt_iron_spear_kp", t.player.by_symbol("npc", "tbwt_tamayu"))
            t.exec("giveSpear-dialog", t.chat.play, {
                "player:Tamayu, try using this weapon",
                "mesbox:You hand the spear",
                "npc:Thank you Bwana",
            })
            t.ticks(2)
            -- LEG 3 END
            local _, l3stage = t.quest.stage()
            local _, l3tile = t.world.tile()
            local _, tam = t.var.server("varp6053_tbwt_tamayu")
            t.check("leg.3.end", tam == 3, "tile " .. tostring(l3tile.x) .. "," .. tostring(l3tile.z) .. " level " .. tostring(l3tile.level) .. ", varp320_tbwt_main=" .. tostring(l3stage) .. ", varp6053_tbwt_tamayu=" .. tostring(tam) .. ", Tamayu holds the poisoned spear and the agility potion; pack: banana rum, marinated burnt bones, seaweed, knife, tinderbox, sharks")
        end },
        { name = "hunt_to_end", run = function(t)
            -- LEG 4 BEGIN: goOnHuntToKill
            t.ticks(3)
            t.exec("goOnHuntToKill", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("goOnHuntToKill-dialog", t.chat.play, {
                "options",
                "choose:/Take me on your next hunt/",
                "player:Take me on your next hunt",
                "npc:Very well, but you must not interfere",
            })
            t.exec("goOnHuntToKill.cutscene", t.cutscene.await, "goOnHuntToKill", { expect = { { op = "reset" } } })
            t.ticks(4)
            local _, tam = t.var.server("varp6053_tbwt_tamayu")
            t.check("goOnHuntToKill.var", tam == 4, "varp6053_tbwt_tamayu = " .. tostring(tam) .. " after the killing hunt")

            -- getMonkeyCorpse: the corpse drops only for a monkey killed at range or by magic (tbwt_monkey.rs2:20-31, :53-60)
            t.exec("goto-getMonkeyCorpse", t.player.goto_tile, 2834, 3032, 0)
            -- wind strike does 1-2 damage to a 3-hit-point monkey (30 in the client's tenths): re-cast until its corpse lies on the ground
            local casts, corpse_down = 0, false
            while casts < 30 and not corpse_down do
                casts = casts + 1
                local cr0, cd0 = t.player.cast("wind_strike", "monkey", 8)
                if casts == 1 then t.check("getMonkeyCorpse", cr0 == "ok", "first wind strike: " .. tostring(cd0)) end
                t.ticks(3)
                corpse_down = (t.world.obj_near("tbwt_monkey_corpse", 8) == "ok")
            end
            t.check("getMonkeyCorpse-dead", corpse_down, "monkey killed with wind strike after " .. tostring(casts) .. " cast(s); tbwt_monkey_corpse on the ground: " .. tostring(corpse_down))
            -- pickupCorpse: Take on the dropped tbwt_monkey_corpse
            t.exec("pickupCorpse", t.player.click_obj, "tbwt_monkey_corpse", 3)
            local cr, cn = t.inv.await("tbwt_monkey_corpse", 1, 20)
            t.check("pickupCorpse.has", cr == "ok", "monkey corpse in the backpack: " .. tostring(cn))

            -- useCorpseOnTamayu: tbwt_tamayu.rs2:48-74 -- he skins it now that he has slain the Shaikahan
            t.exec("goto-useCorpseOnTamayu", t.player.goto_tile, 2846, 3040, 0)
            t.exec("useCorpseOnTamayu", t.player.use_on, "tbwt_monkey_corpse", t.player.by_symbol("npc", "tbwt_tamayu"))
            t.exec("useCorpseOnTamayu-dialog", t.chat.play, {
                "npc:Let me guess",
                "mesbox:You hand over the monkey corpse to Tamayu",
            })
            t.ticks(6)
            t.exec("useCorpseOnTamayu-skin", t.chat.play, { "mesbox:Tamayu hands you some monkey skin and bones" })
            t.ticks(2)
            local _, skin = t.inv.count("tbwt_monkey_skin")
            t.check("useCorpseOnTamayu.has", skin == 1, "monkey skin in the backpack: " .. tostring(skin))

            -- makeSeaweedSandwich: tbwt_monkey_skin is the clicked item (quest_tbwt.rs2 [opheldu,tbwt_monkey_skin])
            t.exec("makeSeaweedSandwich", t.player.use_item_on_item, "seaweed", "tbwt_monkey_skin")
            t.ticks(2)
            local _, sw = t.inv.count("tbwt_seaweed_in_monkey_skin_sandwich")
            t.check("makeSeaweedSandwich.has", sw == 1, "seaweed in monkey skin sandwiches: " .. tostring(sw))

            -- talkToTinsay: Cairn Isle (2764,2975), plain travel (the guide names fairy ring CKR only as the way there)
            t.exec("goto-talkToTinsay", t.player.goto_tile, 2764, 2977, 0)
            t.exec("talkToTinsay", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-dialog", t.chat.play, {
                "npc:Braaar! Tinsay's the name",
                "player:Tinsay, I bring good news",
                "player:Your father requests",
                "npc:I will return only once",
                "player:Where is the tribal statue",
                "npc:Just near my father's hut",
                "player:But that's in the village",
                "npc:I know.",
                "player:So what are you doing here",
                "npc:I'm",
                "player:And I suppose you want me",
                "npc:Good idea",
                "player:You mean you were just sitting",
                "npc:Yes...",
                "player:And you don't see anything wrong",
                "npc:No...",
                "player:Right",
            })
            t.ticks(8)
            t.exec("talkToTinsay-dialog2", t.chat.play, {
                "npc:Hmm ... I think I need banana",
                "player:I see. And you're going to use this",
                "npc:But of course",
                "player:... I'll be back later",
            })
            t.ticks(2)
            local _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay.var", tin == 2, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " after the first talk (fetch banana rum)")

            -- talkToTinsay (2nd visit): banana in Karamjan rum, tbwt_tinsay.rs2:272-285
            t.exec("talkToTinsay-banana", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-banana-dialog", t.chat.play, {
                "npc:Have you found my banana in Karamjan rum",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the sliced bananas",
            })
            t.ticks(8)
            t.exec("talkToTinsay-banana-dialog2", t.chat.play, {
                "npc:Yes ... that's it",
                "player:What? I thought you needed",
                "npc:I did!",
                "player:Can we return to the village now",
                "npc:Not yet",
                "player:What is it?",
                "npc:I'm thinking",
            })
            t.ticks(8)
            t.exec("talkToTinsay-banana-dialog3", t.chat.play, {
                "npc:Seaweed ... Yes",
                "npc:Aha!",
                "player:Is this really necessary",
                "npc:Yes. Essential",
                "player:I'll be back later",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-banana.var", tin == 4, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (fetch_seaweedsandwich)")

            -- talkToTinsay (3rd visit): the seaweed in monkey skin sandwich
            t.exec("talkToTinsay-sandwich", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-sandwich-dialog", t.chat.play, {
                "npc:Have you found my seaweed in monkey skin sandwich",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the seaweed in monkey skin sandwich",
            })
            t.ticks(8)
            t.exec("talkToTinsay-sandwich-dialog2", t.chat.play, {
                "npc:Yes ... perfect",
                "player:Can we go now",
                "npc:Erm",
                "player:...",
                "npc:...",
                "player:...",
                "npc:...",
                "player:Say something",
                "npc:No!",
                "player:Does that mean",
                "npc:I'm not coming",
                "player:Why?",
                "npc:I need one more thing",
                "player:Jogre bones?",
                "npc:Yes ... burnt Jogre bones",
                "player:... burnt Jogre bones??",
                "npc:Indeed",
                "player:Marinated???",
                "npc:Marinated in Karambwanji",
                "player:...",
                "npc:Mmm",
                "player:You're just going to eat it",
                "npc:No! Burnt Jogre bones",
                "player:I'll be back",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-sandwich.var", tin == 6, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (fetch_marinatedbones)")

            -- talkToTinsay (4th visit): the burnt jogre bones marinated in karambwanji
            t.exec("talkToTinsay-bones", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-bones-dialog", t.chat.play, {
                "npc:Have you found my burnt Jogre bones marinated",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the burnt Jogre bones marinated",
            })
            t.ticks(14)
            t.exec("talkToTinsay-bones-dialog2", t.chat.play, {
                "npc:Finally!",
                "player:I assume you're now able",
                "npc:Perfectly able",
                "npc:Probably best you don't",
                "player:Will you return to the village now",
                "npc:Must I",
                "player:I insist",
                "npc:He will not be pleased",
                "player:Why?",
                "npc:It's complicated",
                "npc:Very well. I will meet you",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-bones.var", tin == 7, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (complete)")

            -- useVesselOnTinsay: tbwt_tinsay.rs2:46-72 -- the plain vessel Tiadeche sent along, now that Tinsay is satisfied
            t.exec("useVesselOnTinsay", t.player.use_on, "tbwt_karambwan_vessel", t.player.by_symbol("npc", "tbwt_tinsay"))
            t.exec("useVesselOnTinsay-dialog", t.chat.play, {
                "player:Your brother Tiadeche has sent me",
                "npc:Very well - hand it over",
                "mesbox:You hand over the Karambwan vessel to Tinsay",
