            t.ticks(2)
            local _, tia = t.var.varp("varp321_tbwt_tiadeche")
            local _, mainstage = t.quest.stage()
            t.check("goToTiadecheFinal.var", mainstage == 4, "varp321_tbwt_tiadeche = " .. tostring(tia) .. ", varp320_tbwt_main = " .. tostring(mainstage) .. " (completed_all_brothers)")

            -- goToTimfrakuLadderEnd: back up the ladder into Timfraku's hut (as in leg 1)
            t.exec("goto-goToTimfrakuLadderEnd", t.player.goto_tile, 2781, 3089, 0)
            t.exec("goToTimfrakuLadderEnd", t.player.click_loc, "ladder", 1)
            t.ticks(4)
            local _, end_level = t.world.level()
            t.check("goToTimfrakuLadderEnd.level", end_level == 1, "after the ladder the player is on level " .. tostring(end_level))
            -- LEG 4 END of the pre-hand-in rows; the hand-in follows
            local snap = t.skill.snapshot()
            local _, qp_before = t.var.varp("varp101_qp")

            -- talkToTimfrakuEnd: the option chosen does not matter (tbwt_timfraku.rs2:259-290)
            local coins_before = select(2, t.inv.count("coins"))
            t.exec("talkToTimfrakuEnd", t.player.talk_to, "tbwt_timfraku", 1)
            t.exec("talkToTimfrakuEnd-dialog", t.chat.play, {
                "npc:My sons have returned to the village",
                "npc:please accept my eternal gratitude",
                "options",
                "choose:Oh it was nothing really.",
                "player:Oh it was nothing really",
                "npc:It was? Very well",
                "player:Of course.",
                "mesbox:Timfraku hands you a big stack of gold coins",
            })
            t.ticks(4)
            -- the quest-complete queue also runs tbwt_timfraku_talk_to_sons (quest_tbwt.rs2:317): dismiss it before the scroll check
            t.exec("talkToTimfrakuEnd-sons", t.chat.play, {
                "npc:You should go and see my sons",
                "options",
                "choose:Ok, thanks.",
                "player:Ok, thanks",
            })
            t.ticks(4)
            local _, coins_after = t.inv.count("coins")
            t.check("talkToTimfrakuEnd.coins", coins_after == coins_before + 2000, "coins " .. tostring(coins_before) .. " -> " .. tostring(coins_after) .. " (documented reward: 2000 coins)")
            -- expect_complete's own quest.journal row times out right after scroll.close() (gaps-combat: `quest.journal` can
            -- time out after a real completion), so the four-row shape is written by hand with the rows that land.
            local stage_r, stage_v = t.quest.stage()
            t.check("quest.varp_complete", stage_r == "ok" and stage_v == 6, "varp320_tbwt_main = " .. tostring(stage_v) .. " (complete=6) [" .. tostring(stage_r) .. "]")
            local sr, sd = t.scroll.title()
            local sname = type(sd) == "table" and sd.name or nil
            local shr, shd = t.shot("quest.scroll")
            local shnote = ""
            if shr == "ok" and type(shd) == "string" and string.find(shd, "unchanged", 1, true) then shnote = " [scroll already photographed: " .. shd .. "]" end
            t.step("quest.scroll_title", (sr == "ok" and type(sname) == "string" and string.find(sname, "Tai Bwo Wannai Trio", 1, true) ~= nil) and "PASS" or "FAIL", "scroll title: " .. tostring(sname) .. " (" .. tostring(sr) .. ")" .. shnote)
            local rr, rd = t.scroll.rewards()
            local rtext = type(rd) == "table" and type(rd.lines) == "table" and table.concat(rd.lines, " | ") or tostring(rd)
            t.check("quest.scroll_rewards", rr == "ok" and string.find(rtext, "2 Quest Points", 1, true) ~= nil, "reward scroll lists: " .. rtext)
            -- the scroll lists the four XP rewards (wiki scroll image); the brothers award them below
            for _, pair in ipairs({ { "Fishing", 5000 }, { "Cooking", 5000 }, { "Attack", 2500 }, { "Strength", 2500 } }) do
                local xr, xv = t.scroll.reward_xp(pair[1])
                t.check("quest.scroll_xp." .. pair[1], xr == "ok" and xv == pair[2], pair[1] .. " XP on the scroll: " .. tostring(xr) .. " " .. tostring(xv))
            end
            local cr2 = t.scroll.close()
            t.check("quest.scroll_close", cr2 == "ok", "scroll.close() -> " .. tostring(cr2))
            local qp_r, qp_now = t.var.varp("varp101_qp")
            t.check("quest.points", qp_r == "ok" and qp_now == qp_before + 2, "qp " .. tostring(qp_before) .. " -> " .. tostring(qp_now) .. " (documented reward: 2 Quest Points)")

            -- The XP rewards are claimed from the three brothers in the village after completion
            -- (wiki Tai Bwo Wannai Trio oldid 15265886 Rewards; Quest Helper talkToTimfrakuEnd NOTE;
            -- tbwt_tinsay_final / tbwt_tiadeche_final / tbwt_tamayu_final .rs2 claim_reward).
            t.exec("goto-claimTinsay", t.player.goto_tile, 2790, 3052, 0)
            local _, s1 = t.skill.snapshot()
            t.exec("claimTinsay", t.player.talk_to, "tbwt_tinsay_multinpc_house", 1)
            t.exec("claimTinsay-dialog", t.chat.play, {
                "npc:Braaar! Your meals are truly excellent",
                "player:I'm glad to hear it.",
                "npc:but there are some areas",
                "player:Such as?",
                "npc:Let me show you.",
                "mesbox:Tinsay trains you in cooking technique.",
                "mesbox:Tinsay teaches you how to cook Karambwan",
                "player:Thanks.",
                "npc:Oh, and before you go",
                "player:Ok...",
            })
            t.ticks(2)
            t.exec("claimTinsay.xp", t.skill.expect_gain, "cooking", 5000, s1)

            t.exec("goto-claimTiadeche", t.player.goto_tile, 2781, 3055, 0)
            local _, s2 = t.skill.snapshot()
            t.exec("claimTiadeche", t.player.talk_to, "tbwt_tiadeche_multinpc_house", 1)
            t.exec("claimTiadeche-dialog", t.chat.play, {
                "npc:Hello, Bwana! We three have finally returned",
                "player:So I see.",
                "npc:I wish to reward you",
                "npc:I have refined my Karambwan fishing technique",
                "mesbox:Tiadeche trains you in fishing technique.",
                "npc:Thanks to you, Lubufu's Karambwan monopoly is over",
                "player:Thanks.",
            })
            t.ticks(2)
            t.exec("claimTiadeche.xp", t.skill.expect_gain, "fishing", 5000, s2)

            t.exec("goto-claimTamayu", t.player.goto_tile, 2800, 3055, 0)
            local _, s3 = t.skill.snapshot()
            t.exec("claimTamayu", t.player.talk_to, "tbwt_tamayu_multinpc_house", 1)
            t.exec("claimTamayu-dialog", t.chat.play, {
                "npc:Welcome back to Tai Bwo Wannai, stranger.",
                "player:I no longer feel a stranger here.",
                "npc:And neither do we",
                "npc:I have not much of worth to give",
                "mesbox:Tamayu trains you in fighting technique.",
                "player:Thanks.",
                "npc:This is the one thing I can give",
                "mesbox:Tamayu hands you some kind of spear.",
                "npc:Take care, Bwana.",
            })
            t.ticks(2)
            t.exec("claimTamayu.xp-attack", t.skill.expect_gain, "attack", 2500, s3)
            t.exec("claimTamayu.xp-strength", t.skill.expect_gain, "strength", 2500, s3)
            t.exec("claimTamayu.spear", t.inv.await, "tbwt_rune_spear_kp", 1, 5)
            t.finish(0)
        end },
    },
}
